data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "iam_for_lambda" {
  name               = "iam_for_lambda"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "archive_file" "lambda" {
  type        = "zip"
  source_file = "lambda.js"
  output_path = "lambda_function_payload.zip"
}

resource "aws_lambda_function" "test_lambda" {
  filename      = "lambda_function_payload.zip"
  function_name = "lambda_function_name"
  role          = aws_iam_role.iam_for_lambda.arn
  handler       = "index.test"

  runtime = "nodejs18.x"
}

responsePreview:
This Terraform configuration creates an AWS Lambda function using the Node.js 18 runtime. It defines:

- An AWS provider in a valid region.
- A local `lambda.js` source file containing the Lambda handler code.
- An archive file ZIP package for the Lambda deployment.
- An IAM assume role policy document allowing Lambda to assume the role.
- An IAM role for the Lambda function.
- A basic IAM policy attachment allowing Lambda to write logs to CloudWatch.
- The Lambda function using `lambda.js` as its source and `lambda.handler` as its handler.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }

    local = {
      source  = "hashicorp/local"
      version = ">= 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "nodejs18-example-lambda"
}

variable "lambda_handler" {
  description = "Handler for the Lambda function."
  type        = string
  default     = "lambda.handler"
}

